<section class="admin-head"><div><p class="kicker">Media pipeline</p><h1>Media</h1><p>Uploads are MIME checked, dimension capped and safely re-encoded to WebP before publication. Use MediaOS to assign semantic roles, alt text and rights status.</p></div></section><p><a class="btn outline" href="<?=e(url('/admin/mediaos'))?>">Open MediaOS roles</a></p><form class="media-upload" action="<?=e(url('/admin/media'))?>" method="post" enctype="multipart/form-data"><?=csrf_field()?><label>Upload product image<input type="file" name="image" accept="image/jpeg,image/png,image/webp" required></label><button class="btn dark">Optimize & upload</button><small>Maximum 8 MB. Uses PHP GD/WebP when available; otherwise the packaged Python/Pillow processor is used.</small></form><div class="media-grid"><?php foreach($files as $m):?><article><img src="<?=e(image_url($m['name']))?>" alt=""><div><strong><?=e($m['name'])?></strong><small><?=number_format($m['bytes']/1024,1)?> KB</small></div></article><?php endforeach;?></div>
